using Factory = std::function<std::unique_ptr<Codec>()>;
std::unordered_map<std::string, Factory>& codec_registry() {
    static std::unordered_map<std::string, Factory> r;   // construct on first use
    return r;
}
bool register_codec(const std::string& name, Factory f) {
    return codec_registry().emplace(name, std::move(f)).second;
}
std::unique_ptr<Codec> make_codec(const std::string& name) {
    auto it = codec_registry().find(name);
    return it == codec_registry().end() ? nullptr : it->second();
}

