std::unordered_map<std::string, std::any>& services() {
    static std::unordered_map<std::string, std::any> s;
    return s;
}

template <class T> void put(std::string_view key, T value) {
    services().insert_or_assign(std::string(key), std::move(value));
}

template <class T> T get(std::string_view key) {   // throws bad_any_cast
    return std::any_cast<T>(services().at(std::string(key)));
}

struct Entry { std::string_view name; Factory create; };
template <std::size_t N> struct Table {
    std::array<Entry, N> slots{};
    std::size_t size = 0;
    constexpr bool add(std::string_view n, Factory f) {
        if (size == N) return false;
        slots[size++] = Entry{ n, f };
        return true;
    }
};
struct CodecFactory {
    static inline constinit Table<8> table{};    // constant-initialized
    static constexpr bool reg(std::string_view n, Factory f) {
        return table.add(n, f);
    }
};
